 private const PAYMENT_TYPES=['CASH','CHEQUE','TPE','FANILO','VISA','FMS','CLIENT_VOUCHER','STATION_OPERATION'];
 #[Route('/workspace',methods:['GET'])]public function workspace(Request $r,EntityManagerInterface $em,UserAccessService $access):JsonResponse{if($denied=$access->require([UserAccessService::ROLE_GERANT,UserAccessService::ROLE_QUALITY_MARSHALL,UserAccessService::ROLE_ASSISTANT]))return$denied;$stationId=(int)$r->query->get('station');if(!$stationId)return $this->json(['message'=>'Station obligatoire'],422);$repo=$em->getRepository(Stations::class);$station=$repo->find($stationId);if(!$station)return $this->json(['message'=>'Station introuvable'],404);if(!$access->canAccessStation($station))return$access->denyStation();$tanks=$em->getRepository(FuelTank::class)->findBy(['station'=>$stationId,'isActive'=>true],['name'=>'ASC']);$pumps=$em->getRepository(FuelPump::class)->findBy(['station'=>$stationId,'isActive'=>true],['name'=>'ASC']);$attendants=$em->getRepository(PumpAttendant::class)->findBy(['station'=>$stationId,'isActive'=>true],['fullName'=>'ASC']);$nozzles=[];foreach($em->getRepository(FuelNozzle::class)->findBy(['isActive'=>true]) as $n)if($n->getPump()?->getStation()?->getId()===$stationId)$nozzles[]=$n;$readings=$em->getRepository(FuelShiftReading::class)->findBy(['station'=>$stationId],['workDate'=>'DESC','id'=>'DESC'],50);return $this->json(['fuelTypes'=>array_map(fn($x)=>$this->fuelType($x),$em->getRepository(FuelType::class)->findBy(['isActive'=>true],['code'=>'ASC'])),'tanks'=>array_map(fn($x)=>$this->tank($x),$tanks),'pumps'=>array_map(fn($x)=>$this->pump($x,$nozzles),$pumps),'nozzles'=>array_map(fn($x)=>$this->nozzle($x),$nozzles),'attendants'=>array_map(fn($x)=>['id'=>$x->getId(),'code'=>$x->getCode(),'name'=>$x->getFullName()],$attendants),'readings'=>array_map(fn($x)=>$this->reading($x),$readings),'paymentTypes'=>self::PAYMENT_TYPES]);}
 #[Route('/setup',methods:['POST'])]public function setup(Request $r,EntityManagerInterface $em,UserAccessService $access):JsonResponse{if($denied=$access->require([UserAccessService::ROLE_GERANT,UserAccessService::ROLE_QUALITY_MARSHALL]))return$denied;$d=$r->toArray();$station=$em->getRepository(Stations::class)->find((int)($d['stationId']??0));if(!$station)return $this->json(['message'=>'Station invalide'],422);if(!$access->canAccessStation($station))return$access->denyStation();$type=$d['type']??'';if($type==='FUEL'){$e=(new FuelType())->setCode(strtoupper(trim($d['code']??'')))->setName(trim($d['name']??''));}elseif($type==='TANK'){$fuel=$em->getRepository(FuelType::class)->find((int)($d['fuelTypeId']??0));if(!$fuel)return $this->json(['message'=>'Carburant invalide'],422);$e=(new FuelTank())->setStation($station)->setFuelType($fuel)->setCode(trim($d['code']??''))->setName(trim($d['name']??''))->setCapacity((string)max(0,(float)($d['capacity']??0)))->setCurrentStock((string)max(0,(float)($d['currentStock']??0)))->setMinimumStock((string)max(0,(float)($d['minimumStock']??0)));}elseif($type==='PUMP'){$tank=$em->getRepository(FuelTank::class)->find((int)($d['tankId']??0));if(!$tank||$tank->getStation()?->getId()!==$station->getId())return $this->json(['message'=>'La pompe doit être reliée à une cuve valide.'],422);$code=trim($d['code']??'');$e=(new FuelPump())->setStation($station)->setCode($code)->setName(trim($d['name']??''));$nozzle=(new FuelNozzle())->setPump($e)->setTank($tank)->setCode($code)->setCurrentIndex((string)max(0,(float)($d['currentIndex']??0)))->setUnitPrice((string)max(0,(float)($d['unitPrice']??0)));$em->persist($nozzle);}elseif($type==='NOZZLE'){$pump=$em->getRepository(FuelPump::class)->find((int)($d['pumpId']??0));$tank=$em->getRepository(FuelTank::class)->find((int)($d['tankId']??0));if(!$pump||!$tank||$pump->getStation()?->getId()!==$station->getId()||$tank->getStation()?->getId()!==$station->getId())return $this->json(['message'=>'Pompe ou cuve invalide'],422);$e=(new FuelNozzle())->setPump($pump)->setTank($tank)->setCode(trim($d['code']??''))->setCurrentIndex((string)max(0,(float)($d['currentIndex']??0)))->setUnitPrice((string)max(0,(float)($d['unitPrice']??0)));}elseif($type==='ATTENDANT'){$e=(new PumpAttendant())->setStation($station)->setCode(trim($d['code']??'')?:null)->setFullName(trim($d['name']??''))->setContact(trim($d['contact']??'')?:null);}else return $this->json(['message'=>'Type invalide'],422);$em->persist($e);$em->flush();return $this->json(['id'=>$e->getId()],201);}
 #[Route('/readings',methods:['POST'])]public function createReading(Request $r,EntityManagerInterface $em,UserAccessService $access):JsonResponse{if($denied=$access->require([UserAccessService::ROLE_GERANT,UserAccessService::ROLE_ASSISTANT]))return$denied;$d=$r->toArray();$station=$em->getRepository(Stations::class)->find((int)($d['stationId']??0));$nozzle=$em->getRepository(FuelNozzle::class)->find((int)($d['nozzleId']??0));$attendant=$em->getRepository(PumpAttendant::class)->find((int)($d['attendantId']??0));if($station&&!$access->canAccessStation($station))return$access->denyStation();if(!$station||!$nozzle||!$attendant||$nozzle->getPump()?->getStation()?->getId()!==$station->getId()||$attendant->getStation()?->getId()!==$station->getId())return $this->json(['message'=>'Références invalides'],422);$start=(float)($d['startIndex']??0);$end=(float)($d['endIndex']??0);$rc=max(0,(float)($d['returnToTank']??0));$output=$end-$start;$sold=$output-$rc;$price=max(0,(float)($d['unitPrice']??$nozzle->getUnitPrice()));if($output<0||$sold<0)return $this->json(['message'=>'Les index ou le RC sont incohérents'],422);$payments=[];$paid=0;foreach(($d['payments']??[]) as $p){$type=strtoupper($p['type']??'');$amount=max(0,(float)($p['amount']??0));if(!in_array($type,self::PAYMENT_TYPES,true))return $this->json(['message'=>'Mode de paiement invalide'],422);if($amount>0){$payments[]=['type'=>$type,'amount'=>$amount,'reference'=>trim($p['reference']??'')?:null];$paid+=$amount;}}$total=round($sold*$price,2);if(abs($paid-$total)>.01)return $this->json(['message'=>sprintf('Ventilation incorrecte : %.2f Ar attendus, %.2f Ar saisis',$total,$paid)],422);$tank=$nozzle->getTank();if((float)$tank->getCurrentStock()<$sold)return $this->json(['message'=>'Stock cuve insuffisant'],422);$reading=(new FuelShiftReading())->setStation($station)->setNozzle($nozzle)->setAttendant($attendant)->setWorkDate(new \DateTimeImmutable($d['date']??'today'))->setStartIndex((string)$start)->setEndIndex((string)$end)->setReturnToTank((string)$rc)->setQuantitySold((string)$sold)->setUnitPrice((string)$price)->setTotalAmount((string)$total)->setPayments($payments)->setCreatedAt(new \DateTimeImmutable());$nozzle->setCurrentIndex((string)$end);$tank->setCurrentStock((string)((float)$tank->getCurrentStock()-$sold));$em->persist($reading);$em->flush();return $this->json($this->reading($reading),201);}
 #[Route('/deliveries',methods:['POST'])]public function delivery(Request $r,EntityManagerInterface $em,UserAccessService $access):JsonResponse{if($denied=$access->require(UserAccessService::ROLE_GERANT))return$denied;$d=$r->toArray();$station=$em->getRepository(Stations::class)->find((int)($d['stationId']??0));$tank=$em->getRepository(FuelTank::class)->find((int)($d['tankId']??0));$qty=max(0,(float)($d['quantity']??0));$cost=max(0,(float)($d['unitCost']??0));if($station&&!$access->canAccessStation($station))return$access->denyStation();if(!$station||!$tank||$tank->getStation()?->getId()!==$station->getId()||$qty<=0)return $this->json(['message'=>'Livraison invalide'],422);if((float)$tank->getCurrentStock()+$qty>(float)$tank->getCapacity())return $this->json(['message'=>'La capacité de la cuve serait dépassée'],422);$e=(new FuelDelivery())->setStation($station)->setTank($tank)->setSupplier(trim($d['supplier']??''))->setInvoiceNumber(trim($d['invoiceNumber']??'')?:null)->setDeliveryDate(new \DateTimeImmutable($d['date']??'today'))->setQuantity((string)$qty)->setUnitCost((string)$cost)->setTotalAmount((string)round($qty*$cost,2))->setCreatedAt(new \DateTimeImmutable());$tank->setCurrentStock((string)((float)$tank->getCurrentStock()+$qty));$em->persist($e);$em->flush();return $this->json(['id'=>$e->getId()],201);}
 private function fuelType(FuelType $x):array{return ['id'=>$x->getId(),'code'=>$x->getCode(),'name'=>$x->getName()];}private function tank(FuelTank $x):array{return ['id'=>$x->getId(),'code'=>$x->getCode(),'name'=>$x->getName(),'fuel'=>$x->getFuelType()?->getCode(),'fuelTypeId'=>$x->getFuelType()?->getId(),'capacity'=>(float)$x->getCapacity(),'stock'=>(float)$x->getCurrentStock(),'minimum'=>(float)$x->getMinimumStock()];}private function pump(FuelPump $x,array $nozzles):array{$nozzle=$this->primaryNozzle($x,$nozzles);return ['id'=>$x->getId(),'code'=>$x->getCode(),'name'=>$x->getName(),'tank'=>$nozzle?->getTank()?->getName(),'tankId'=>$nozzle?->getTank()?->getId(),'fuel'=>$nozzle?->getTank()?->getFuelType()?->getCode()];}private function primaryNozzle(FuelPump $pump,array $nozzles):?FuelNozzle{foreach($nozzles as $nozzle)if($nozzle->getPump()?->getId()===$pump->getId())return $nozzle;return null;}private function nozzle(FuelNozzle $x):array{return ['id'=>$x->getId(),'code'=>$x->getCode(),'pump'=>$x->getPump()?->getName(),'pumpId'=>$x->getPump()?->getId(),'tankId'=>$x->getTank()?->getId(),'fuel'=>$x->getTank()?->getFuelType()?->getCode(),'currentIndex'=>(float)$x->getCurrentIndex(),'unitPrice'=>(float)$x->getUnitPrice()];}private function reading(FuelShiftReading $x):array{return ['id'=>$x->getId(),'date'=>$x->getWorkDate()?->format('Y-m-d'),'responsible'=>$x->getAttendant()?->getFullName(),'nozzle'=>$x->getNozzle()?->getCode(),'fuel'=>$x->getNozzle()?->getTank()?->getFuelType()?->getCode(),'startIndex'=>(float)$x->getStartIndex(),'endIndex'=>(float)$x->getEndIndex(),'output'=>(float)$x->getEndIndex()-(float)$x->getStartIndex(),'returnToTank'=>(float)$x->getReturnToTank(),'quantitySold'=>(float)$x->getQuantitySold(),'unitPrice'=>(float)$x->getUnitPrice(),'totalAmount'=>(float)$x->getTotalAmount(),'payments'=>$x->getPayments()];}
